suspend fun loadAll() = supervisorScope {
    val a = async { loadA() }
    val b = async { loadB() }
    val c = async { loadC() }
    listOf(runCatching { a.await() },
           runCatching { b.await() },
           runCatching { c.await() })
}

tailrec fun gcd(a: Int, b: Int): Int =
    if (b == 0) a else gcd(b, a % b)

fun sum(xs: List<Int>, i: Int = 0): Int =
    if (i == xs.size) 0 else xs[i] + sum(xs, i + 1)

